    def asteroidCollision(self, asteroids):
        """
        :type asteroids: List[int]
        :rtype: List[int]
        """
        ans = []
        for cur in asteroids:
            alive = True
            while alive and cur < 0 and ans and ans[-1] > 0:
                alive = ans[-1] < -cur
                if ans[-1] <= -cur:
